mapper.select:
SELECT r.*, u.username as upload_username, u.nickname as upload_nickname, u.avatar_url as upload_avatar, c.name as category_name FROM resource r LEFT JOIN user u ON r.upload_user_id = u.id LEFT JOIN category c ON r.category_id = c.id WHERE 1=1
AND r.status = #{status}
AND r.category_id = #{categoryId}
AND (r.title LIKE CONCAT('%', #{keyword}, '%') OR r.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY r.create_time DESC
